31	struct Link {
32	  Link() : predecessor_(), successor_() {}
33	  Link(const LinkInfo& predecessor, const LinkInfo& successor) : predecessor_(predecessor), successor_(successor) {}
34	  LinkInfo predecessor_;
35	  LinkInfo successor_;
36	  //! getter
37	  LinkInfo get_predecessor() const { return predecessor_; }
38	  LinkInfo get_successor() const { return successor_; }
39	  void set_predecessor(const LinkInfo& info) { predecessor_ = info; }
40	  void set_successor(const LinkInfo& info) { successor_ = info; }
41	};
